#!/usr/bin/env bash
# Question 1: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

case "${Q1_FAULT}" in
  kubelet-max-pods)
    sed -i '/^maxPods:/d' /var/lib/kubelet/config.yaml
    echo 'maxPods: 2' >> /var/lib/kubelet/config.yaml
    systemctl restart kubelet || true
    ;;
esac
